    public static string T(string key) => Strings.TryGetValue(key, out var value) ? (Language == "pl" ? value.Pl : value.En) : key;
    public static string F(string key, params object[] args) => string.Format(Culture, T(key), args);
    public static void Apply(string language)
    {
        Language = language == "pl" ? "pl" : "en";
        CultureInfo.CurrentCulture = Culture;
        CultureInfo.CurrentUICulture = Culture;
        foreach (var key in Strings.Keys) Application.Current.Resources[key] = T(key);
    }
